  if let Some(meta)=self.meta.as_mut(){if meta.terminal_is_empty(){drop(self.meta.take());self.publish(g,metadata())?;return Ok(RetainedHistoryEditStep::Progress)}if meta.fault().is_some(){meta.take_fault_into(&mut self.fault,child)?;}else if meta.partial_is_receivable(){meta.take_partial_into(&mut self.meta_partial,child)?;}else{meta.close_step(source,prior,control,child)?;}let receipt=meta.take_receipt();return self.accept(g,child,receipt)}
